/// Returns `true` iff every element of `a` equals `n`.
///
/// Correctness:
/// - If it returns `true`, then for every valid index `i`, `a[i] == n`.
/// - If it returns `false`, then there exists some valid index `i` with `a[i] != n`.
/// - For an empty slice, it returns `true` (vacuously true).
pub fn all_elements_equal(a: &[i32], n: i32) -> bool {
    a.iter().all(|&x| x == n)
}

